using System;
using System.Collections.Generic;
using Astrea.RunModifiers;
using FMODUnity;
using LittleLeo;
using LittleLeo.Events;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;
using XandUtils;

namespace Astrea;

[CreateAssetMenu(fileName = "PlayerRunData", menuName = "Data/PlayerRunData")]
public class PlayerRunData : ScriptableObject
{
	[Serializable]
	public class RerolledDiceInstance
	{
		public int rerolledAmount;

		public DiceInstance diceInstance;

		public RerolledDiceInstance(int rerolledAmount, DiceInstance diceInstance)
		{
			this.rerolledAmount = rerolledAmount;
			this.diceInstance = diceInstance;
		}
	}

	[Header("Current Character")]
	[SerializeField]
	private Character currentCharacter;

	[SerializeField]
	private Character anyCharacter;

	[Header("Gold")]
	[SerializeField]
	private int startingGold;

	[SerializeField]
	private int startingGoldBuildState;

	[SerializeField]
	private StringEvent OnModifyGold;

	[SerializeField]
	private TransformReference starShardsTransformReference;

	[SerializeField]
	private GameObject gainStarShardsVFX;

	[SerializeField]
	private EventReference gainStarShardsSFX;

	[SerializeField]
	private EventReference spendStarShardsSFX;

	[Header("Achievements")]
	[SerializeField]
	private AchievementData shardSpenderAchievementData;

	[SerializeField]
	private SaveSystem saveSystem;

	[SerializeField]
	private GottatinkeremallAchievementData gottatinkeremallAchievementData;

	[SerializeField]
	private AchievementData denyingDestinyAchievementData;

	[Header("Runtime")]
	[HorizontalLine(2f, EColor.Gray)]
	public int CurrentPlayerHearts;

	public int CurrentPlayerMaxHearts;

	private Observer<int> currentGold = new Observer<int>(100);

	public int SentinelShopOrRewardTimesVisitedCounter;

	public int DestroyDiceShopItemBoughtCounter;

	public int DuplicateDiceShopItemBoughtCounter;

	public bool AstreaFirstPhaseDefeatedStartBattleOnAstreaSecondPhase;

	public string HiddenAnomalyLevelSecondBossPackageName;

	public bool HiddenAnomalyLevelFirstBossDefeatedStartBattleOnSecondBoss;

	public int CurrentRunAnomalyLevel = -1;

	public int CurrentRunAstreaLevel = -1;

	[Header("Runtime: Statistics")]
	public int StarShardsSpentAmount;

	public int DiceFacesForgedAmount;

	public int DiceDestroyedAmount;

	public int DiceDuplicatedAmount;

	public int VirtuesUsedAmount;

	[Header("Runtime: Achievements")]
	public int HighestPurification;

	[NonSerialized]
	public int DiceUsedAmount;

	[NonSerialized]
	public List<RerolledDiceInstance> RerolledDiceInstances = new List<RerolledDiceInstance>();

	[Header("Tutorial Run and Warnings")]
	[HorizontalLine(2f, EColor.Gray)]
	public bool DisableSentinelDiceTutorialRunWarning;

	public bool SentinelShopTutorialShowed;

	public bool HandLimitWarningShowedInThisRun;

	public bool HandFullWarningShowedInThisRun;

	[NonSerialized]
	public int EnhancedDiceAmount;

	[NonSerialized]
	public int ConvertedDiceAmount;

	[NonSerialized]
	public int CorruptedTimesAmount;

	[NonSerialized]
	public int VirtuesUsedAmountAchievement;

	[NonSerialized]
	public int RearmedSentinelAmount;

	[NonSerialized]
	public int RepairedSentinelAmount;

	[NonSerialized]
	public int BrokenSentinelAmount;

	[NonSerialized]
	public int RecycledSentinelAmount;

	[NonSerialized]
	public int ApianSkyFallAmount;

	[NonSerialized]
	public int RandomPurifyAmount;

	[NonSerialized]
	public int DodgeInARowAmount;

	[NonSerialized]
	public int OrbsMovedAmount;

	[NonSerialized]
	public int GoddessVerdictAmount;

	[NonSerialized]
	public int AstriumActivatedAmount;

	[NonSerialized]
	public int CosmicOrbCastedAmount;

	[NonSerialized]
	public int OrbsMovedWholeBattleAmount;

	[NonSerialized]
	public int RerolledDiceAmount;

	[NonSerialized]
	public int ShuffledPoolAmount;

	public Character CurrentCharacter => currentCharacter;

	public CharacterProgression CurrentCharacterProgression => currentCharacter.CharacterProgression;

	public int CurrentCharacterCurrentAnomalyLevel => CurrentCharacterProgression.CurrentAnomalyLevel;

	public bool CurrentRunAnomalyLevelActive => CurrentRunAnomalyLevel > 0;

	public int CurrentCharacterCurrentAstreaLevel => CurrentCharacterProgression.CurrentAstreaLevel;

	public bool CurrentRunAstreasHeartEnabled => CurrentRunAstreaLevel > 0;

	public Character AnyCharacter => anyCharacter;

	public AchievementData ShardSpenderAchievementData => shardSpenderAchievementData;

	public int CurrentGold => currentGold.Value;

	public Observer<int> CurrentGoldObserver => currentGold;

	public int RearmedAndRepairedSentinelAmount => RearmedSentinelAmount + RepairedSentinelAmount;

	public void SetCurrentCharacter(Character character)
	{
		currentCharacter = character;
	}

	public void OnReset()
	{
		InitializeBattle();
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.1f, delegate
		{
			OnModifyGold.Raise(CurrentGold.ToString());
		});
	}

	[Button(null)]
	public void OnResetToStartRunState()
	{
		CurrentPlayerMaxHearts = ((ReferenceSingleton<RunModifiersManager>.Instance.HeartModificationRunModifier != null) ? ReferenceSingleton<RunModifiersManager>.Instance.HeartModificationRunModifier.RunModifierVariableAmount : currentCharacter.StartingHearts);
		CurrentPlayerHearts = CurrentPlayerMaxHearts;
		currentGold.Value = ((ReferenceSingleton<RunModifiersManager>.Instance.StellarHeritageRunModifier != null) ? ReferenceSingleton<RunModifiersManager>.Instance.StellarHeritageRunModifier.RunModifierVariableAmount : startingGold);
		SentinelShopOrRewardTimesVisitedCounter = 0;
		DestroyDiceShopItemBoughtCounter = 0;
		DuplicateDiceShopItemBoughtCounter = 0;
		HighestPurification = 0;
		DiceFacesForgedAmount = 0;
		DiceDestroyedAmount = 0;
		DiceDuplicatedAmount = 0;
		VirtuesUsedAmount = 0;
		StarShardsSpentAmount = 0;
		AstreaFirstPhaseDefeatedStartBattleOnAstreaSecondPhase = false;
		Debug.Log("AstreaFirstPhaseDefeatedStartBattleOnAstreaSecondPhase: " + AstreaFirstPhaseDefeatedStartBattleOnAstreaSecondPhase);
		if (!gottatinkeremallAchievementData.IsUnlocked())
		{
			gottatinkeremallAchievementData.gottatinkeremallCompanionsCollectedList.Clear();
		}
		DisableSentinelDiceTutorialRunWarning = saveSystem.IsSentinelTutorialWarningPlayed();
		SentinelShopTutorialShowed = saveSystem.IsSentinelShopTutorialShowed();
		HandLimitWarningShowedInThisRun = false;
		HandFullWarningShowedInThisRun = false;
	}

	public void OnResetToStartRunStateBeforeMapPopulate()
	{
		if (ReferenceSingleton<AssetsReference>.Instance.GameController.IsDailyRun)
		{
			CurrentRunAnomalyLevel = 0;
			CurrentRunAstreaLevel = (ReferenceSingleton<RunModifiersManager>.Instance.AstreasHeartActive ? 1 : 0);
		}
		else
		{
			CurrentRunAnomalyLevel = CurrentCharacterCurrentAnomalyLevel;
			CurrentRunAstreaLevel = CurrentCharacterCurrentAstreaLevel;
		}
		HiddenAnomalyLevelSecondBossPackageName = "";
		HiddenAnomalyLevelFirstBossDefeatedStartBattleOnSecondBoss = false;
	}

	public void InitializeBattle()
	{
		EnhancedDiceAmount = 0;
		ConvertedDiceAmount = 0;
		RearmedSentinelAmount = 0;
		RepairedSentinelAmount = 0;
		BrokenSentinelAmount = 0;
		RecycledSentinelAmount = 0;
		CorruptedTimesAmount = 0;
		RerolledDiceAmount = 0;
		ShuffledPoolAmount = 0;
		RandomPurifyAmount = 0;
		GoddessVerdictAmount = 0;
		DodgeInARowAmount = 0;
		OrbsMovedWholeBattleAmount = 0;
		CosmicOrbCastedAmount = 0;
	}

	public void RestartEffectsPerTurnCounters()
	{
		ApianSkyFallAmount = 0;
		OrbsMovedAmount = 0;
		DiceUsedAmount = 0;
		if (!denyingDestinyAchievementData.IsUnlocked())
		{
			RerolledDiceInstances.Clear();
		}
		VirtuesUsedAmount = 0;
		AstriumActivatedAmount = 0;
	}

	public void ModifyGold(int amount)
	{
		if (amount > 0)
		{
			if (!ReferenceSingleton<MiscOmensHandler>.Instance.IsCrimsomVaultActive() && ReferenceSingleton<RunModifiersManager>.Instance.StellarHeritageRunModifier == null)
			{
				ReferenceSingleton<PoolHandler>.Instance.GetObject(gainStarShardsVFX.name, starShardsTransformReference.value.position, 4f);
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(gainStarShardsSFX);
				if (ReferenceSingleton<RunModifiersManager>.Instance.StarShowerRunModifier)
				{
					amount *= 2;
				}
				currentGold.Value += amount;
				OnModifyGold.Raise(CurrentGold.ToString());
			}
		}
		else
		{
			StarShardsSpentAmount += Mathf.Abs(amount);
			if (!shardSpenderAchievementData.IsUnlocked() && StarShardsSpentAmount >= shardSpenderAchievementData.AchievementVariableAmount)
			{
				saveSystem.DeleteStarShardsSpentAmountSaveString();
				shardSpenderAchievementData.Unlock();
			}
			currentGold.Value += amount;
			OnModifyGold.Raise(CurrentGold.ToString());
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(spendStarShardsSFX);
		}
	}

	public void SetGold(int newGold)
	{
		currentGold.Value = newGold;
	}

	public void SentinelShopOrRewardVisited()
	{
		SentinelShopOrRewardTimesVisitedCounter++;
	}

	public void DestroyDiceShopItemBought()
	{
		DestroyDiceShopItemBoughtCounter++;
	}

	public void DuplicateDiceShopItemBought()
	{
		DuplicateDiceShopItemBoughtCounter++;
	}

	public int GetAnomalyLevelUnlockedNumberForUnlockables()
	{
		if (CurrentRunAnomalyLevel == -1)
		{
			return 1;
		}
		return CurrentRunAnomalyLevel + 1;
	}

	public int GetAstreaLevelUnlockedNumberForUnlockables()
	{
		if (CurrentRunAstreaLevel == -1)
		{
			return 1;
		}
		return CurrentRunAstreaLevel + 1;
	}

	public void SetHighestPurification(int newValue)
	{
		if (newValue > HighestPurification)
		{
			HighestPurification = newValue;
		}
	}

	public void AddReroledDiceAmount(int amount)
	{
		RerolledDiceAmount += amount;
	}

	public void AddEnhancedDiceAmount(int amount)
	{
		EnhancedDiceAmount += amount;
	}

	public void AddConvertedDiceAmount(int amount)
	{
		ConvertedDiceAmount += amount;
	}

	public void DiceInstanceRerolledListAndCheckAchievement(List<DiceInstance> diceInstances)
	{
		if (denyingDestinyAchievementData.IsUnlocked())
		{
			return;
		}
		for (int i = 0; i < diceInstances.Count; i++)
		{
			IncreaseDiceInstanceRerolledAndCheckAchievement(diceInstances[i]);
			if (denyingDestinyAchievementData.IsUnlocked())
			{
				break;
			}
		}
	}

	private void IncreaseDiceInstanceRerolledAndCheckAchievement(DiceInstance diceInstance)
	{
		for (int i = 0; i < RerolledDiceInstances.Count; i++)
		{
			if (RerolledDiceInstances[i].diceInstance == diceInstance)
			{
				RerolledDiceInstances[i].rerolledAmount++;
				if (RerolledDiceInstances[i].rerolledAmount >= denyingDestinyAchievementData.AchievementVariableAmount)
				{
					denyingDestinyAchievementData.Unlock();
					RerolledDiceInstances.Clear();
				}
				return;
			}
		}
		RerolledDiceInstances.Add(new RerolledDiceInstance(1, diceInstance));
	}

	public void RemoveDiceRerolledFromRerolledDiceInstances(DiceInstance diceInstance)
	{
		if (denyingDestinyAchievementData.IsUnlocked())
		{
			return;
		}
		for (int num = RerolledDiceInstances.Count - 1; num >= 0; num--)
		{
			if (RerolledDiceInstances[num].diceInstance == diceInstance)
			{
				RerolledDiceInstances.RemoveAt(num);
				break;
			}
		}
	}

	[Button(null)]
	public void GainOneHeart()
	{
		CurrentPlayerHearts++;
	}
}
